// Core Probe Sweep Minigame Modal
const CoreProbeSweepModal = React.memo(({
  onSuccess,
  onFailure,
  onClose,
}: {
  onSuccess: () => void;
  onFailure: () => void;
  onClose: () => void;
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [activeRing, setActiveRing] = useState(0); // 0, 1, 2, or 3 (complete)
  const [ringResults, setRingResults] = useState<Array<'pending' | 'hit' | 'miss'>>(['pending', 'pending', 'pending']);
  const [hits, setHits] = useState(0);
  const hitsRef = useRef(0);
  hitsRef.current = hits;
  const activeRingRef = useRef(0);
  activeRingRef.current = activeRing;
  const sweepAngleRef = useRef(0);
  const isCompletedRef = useRef(false);

  // Deterministic target timing bands (no random rolls)
  // Ring 0: Inner (radius 48px), 45° to 98° (0.78 to 1.71 rad, ~53° arc)
  // Ring 1: Middle (radius 86px), 155° to 210° (2.70 to 3.66 rad, ~55° arc)
  // Ring 2: Outer (radius 124px), 270° to 325° (4.71 to 5.67 rad, ~55° arc)
  const RINGS_CONFIG = [
    { radius: 48, start: 0.78, end: 1.71, label: 'RING 1 · INNER' },
    { radius: 86, start: 2.70, end: 3.66, label: 'RING 2 · MID' },
    { radius: 124, start: 4.71, end: 5.67, label: 'RING 3 · OUTER' },
  ];

  const triggerPulse = useCallback(() => {
    if (isCompletedRef.current) return;
    const cur = activeRingRef.current;
    if (cur >= 3) return;

    const angle = ((sweepAngleRef.current % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
    const ring = RINGS_CONFIG[cur];
    const isHit = angle >= ring.start && angle <= ring.end;

    if (isHit) {
      gameAudio.playBlip();
      hitsRef.current += 1;
      setHits(hitsRef.current);
      setRingResults((prev) => {
        const next = [...prev];
        next[cur] = 'hit';
        return next;
      });
    } else {
      gameAudio.playErrorBuzz();
      setRingResults((prev) => {
        const next = [...prev];
        next[cur] = 'miss';
        return next;
      });
    }

    const nextRing = cur + 1;
    activeRingRef.current = nextRing;
    setActiveRing(nextRing);

    if (nextRing >= 3) {
      isCompletedRef.current = true;
      setTimeout(() => {
        if (hitsRef.current >= 2) {
          onSuccess();
        } else {
          onFailure();
        }
      }, 450);
    }
  }, [onSuccess, onFailure]);

  // Keyboard navigation & pulse listener
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      if (k === 'p' || e.code === 'KeyP' || e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        e.stopPropagation();
        triggerPulse();
      } else if (e.key === 'Escape' || e.code === 'Escape') {
        if (e.repeat) return;
        e.preventDefault();
        e.stopPropagation();
        onClose();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [triggerPulse, onClose]);

  // Radar drawing loop
  useEffect(() => {
    let raf = 0;
    let lastTime = performance.now();

    const render = (time: number) => {
      const dt = Math.min(0.05, (time - lastTime) / 1000);
      lastTime = time;

      // Deterministic rotation speed 2.6 rad/s
      sweepAngleRef.current = (sweepAngleRef.current + 2.6 * dt) % (Math.PI * 2);

      const canvas = canvasRef.current;
      if (canvas) {
        const ctx = canvas.getContext('2d');
        if (ctx) {
          const w = canvas.width;
          const h = canvas.height;
          const cx = w / 2;
          const cy = h / 2;

          ctx.clearRect(0, 0, w, h);

          // Deep well background
          ctx.fillStyle = '#0F1424';
          ctx.fillRect(0, 0, w, h);

          // Crosshairs
          ctx.strokeStyle = 'rgba(46, 196, 182, 0.15)';
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(cx, 16);
          ctx.lineTo(cx, h - 16);
          ctx.moveTo(16, cy);
          ctx.lineTo(w - 16, cy);
          ctx.stroke();

          // Concentric grid pips
          for (let r = 20; r <= 140; r += 20) {
            ctx.strokeStyle = 'rgba(46, 196, 182, 0.08)';
            ctx.beginPath();
            ctx.arc(cx, cy, r, 0, Math.PI * 2);
            ctx.stroke();
          }

          // Draw the 3 concentric rings
          RINGS_CONFIG.forEach((ring, idx) => {
            const isCur = idx === activeRingRef.current;
            const res = ringResults[idx];

            // Outer ring line
            ctx.save();
            ctx.lineWidth = isCur ? 3.5 : 2;
            if (res === 'hit') {
              ctx.strokeStyle = '#8BD17C';
              ctx.setLineDash([]);
            } else if (res === 'miss') {
              ctx.strokeStyle = '#FF5A5F';
              ctx.setLineDash([4, 4]);
            } else if (isCur) {
              const pulse = 0.7 + 0.3 * Math.sin(Date.now() * 0.009);
              ctx.strokeStyle = `rgba(46, 196, 182, ${pulse})`;
              ctx.setLineDash([]);
            } else {
              ctx.strokeStyle = 'rgba(174, 182, 202, 0.3)';
              ctx.setLineDash([6, 6]);
            }

            ctx.beginPath();
            ctx.arc(cx, cy, ring.radius, 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();

            // Cyan timing band arc
            ctx.save();
            ctx.lineWidth = 9;
            ctx.lineCap = 'round';
            if (res === 'hit') {
              ctx.strokeStyle = '#8BD17C';
            } else if (res === 'miss') {
              ctx.strokeStyle = 'rgba(255, 90, 95, 0.4)';
            } else if (isCur) {
              ctx.strokeStyle = '#2EC4B6';
            } else {
              ctx.strokeStyle = 'rgba(46, 196, 182, 0.45)';
            }
            ctx.beginPath();
            ctx.arc(cx, cy, ring.radius, ring.start, ring.end);
            ctx.stroke();

            // Dark ink outline on arc band
            ctx.strokeStyle = '#0A0E1A';
            ctx.lineWidth = 2;
            ctx.stroke();
            ctx.restore();

            // Status label indicator near band
            const midAngle = (ring.start + ring.end) / 2;
            const lx = cx + Math.cos(midAngle) * (ring.radius + 16);
            const ly = cy + Math.sin(midAngle) * (ring.radius + 16);
            ctx.font = 'bold 9.5px "JetBrains Mono", monospace';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            if (res === 'hit') {
              ctx.fillStyle = '#8BD17C';
              ctx.fillText('✓ LOCKED', lx, ly);
            } else if (res === 'miss') {
              ctx.fillStyle = '#FF5A5F';
              ctx.fillText('✕ MISSED', lx, ly);
            }
          });

          // Draw radar sweep line and trailing sector
          const sweep = sweepAngleRef.current;
          const maxR = 138;

          // Trailing wedge
          ctx.save();
          const trailAngle = 0.45;
          ctx.fillStyle = 'rgba(46, 196, 182, 0.18)';
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          ctx.arc(cx, cy, maxR, sweep - trailAngle, sweep, false);
          ctx.closePath();
          ctx.fill();

          // Leading sweep line
          ctx.strokeStyle = '#F6EED8';
          ctx.lineWidth = 2.5;
          ctx.beginPath();
          ctx.moveTo(cx, cy);
          ctx.lineTo(cx + Math.cos(sweep) * maxR, cy + Math.sin(sweep) * maxR);
          ctx.stroke();

          // Center emitter hub
          ctx.fillStyle = '#2EC4B6';
          ctx.strokeStyle = '#0A0E1A';
          ctx.lineWidth = 2.5;
          ctx.beginPath();
          ctx.arc(cx, cy, 7, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();

          // Cursor pip on active ring
          const curIdx = Math.min(2, activeRingRef.current);
          const activeR = RINGS_CONFIG[curIdx].radius;
          ctx.fillStyle = '#FFB547';
          ctx.strokeStyle = '#0A0E1A';
          ctx.lineWidth = 2;
          ctx.beginPath();
          ctx.arc(cx + Math.cos(sweep) * activeR, cy + Math.sin(sweep) * activeR, 4.5, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();

          ctx.restore();
        }
      }

      raf = requestAnimationFrame(render);
    };

    raf = requestAnimationFrame(render);
    return () => cancelAnimationFrame(raf);
  }, [ringResults]);

  return (
    <div
      onClick={(e) => e.stopPropagation()}
      onPointerDown={(e) => e.stopPropagation()}
      style={{
        position: 'absolute',
        left: '420px',
        top: '120px',
        width: '440px',
        height: '520px',
        boxSizing: 'border-box',
        zIndex: 80,
        background: '#1A2133',
        border: '3px solid #0A0E1A',
        borderRadius: '16px',
        boxShadow: '6px 6px 0 #0A0E1A',
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden',
      }}>
      {/* Title band */}
      <div
        style={{
          height: '34px',
          minHeight: '34px',
          background: '#2EC4B6',
          borderBottom: '3px solid #0A0E1A',
          padding: '0 14px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          boxSizing: 'border-box',
          flexShrink: 0,
        }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span
            style={{
              fontFamily: "'Fredoka', cursive, sans-serif",
              fontWeight: 700,
              fontSize: '16px',
              color: '#0A0E1A',
            }}>
            Core Probe Sweep
          </span>
          <span
            style={{
              background: '#0A0E1A',
              color: '#2EC4B6',
              borderRadius: '5px',
              padding: '1px 6px',
              fontFamily: "'JetBrains Mono', monospace",
              fontSize: '11px',
              fontWeight: 700,
            }}>
            SCANNER
          </span>
        </div>
        <button
          onClick={onClose}
          style={{
            background: 'none',
            border: 'none',
            color: '#0A0E1A',
            cursor: 'pointer',
            padding: '2px',
            display: 'flex',
            alignItems: 'center',
          }}>
          <X size={18} />
        </button>
      </div>

      {/* Subtitle instructions */}
      <div
        style={{
          padding: '10px 16px 6px 16px',
          display: 'flex',
          flexDirection: 'column',
          gap: '2px',
          background: '#1A2133',
          borderBottom: '2px solid #0A0E1A',
        }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <span
            style={{
              fontFamily: "'Inter', sans-serif",
              fontWeight: 700,
              fontSize: '12px',
              color: '#F6EED8',
            }}>
            {activeRing < 3 ? `Resonance Lock: Ring ${activeRing + 1} of 3` : 'Sweep complete'}
          </span>
          <span
            style={{
              fontFamily: "'JetBrains Mono', monospace",
              fontWeight: 700,
              fontSize: '12px',
              color: hits >= 2 ? '#8BD17C' : (activeRing >= 3 ? '#FF5A5F' : '#FFB547'),
            }}>
            Hits: {hits} / 3 (≥2 required)
          </span>
        </div>
        <span
          style={{
            fontFamily: "'Inter', sans-serif",
            fontSize: '11px',
            color: '#AEB6CA',
          }}>
          Press [P] or click radar when the sweep is inside the cyan timing band.
        </span>
      </div>

      {/* Canvas Radar Sweep */}
      <div
        style={{
          flex: 1,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: '#0A0E1A',
          padding: '8px',
          cursor: 'pointer',
        }}
        onClick={triggerPulse}>
        <canvas
          ref={canvasRef}
          width={320}
          height={320}
          style={{
            width: '320px',
            height: '320px',
            border: '2px solid #0A0E1A',
            borderRadius: '12px',
            boxShadow: 'inset 0 0 12px rgba(0,0,0,0.5)',
          }}
        />
      </div>

      {/* Footer controls & pulse button */}
      <div
        style={{
          padding: '10px 14px',
          background: '#1A2133',
          borderTop: '3px solid #0A0E1A',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '10px',
        }}>
        <div
          style={{
            fontFamily: "'Inter', sans-serif",
            fontSize: '11px',
            color: '#AEB6CA',
            display: 'flex',
            alignItems: 'center',
            gap: '4px',
          }}>
          <KeyChip label="P" size="sm" />
          <span>or Click to lock ·</span>
          <KeyChip label="Esc" size="sm" />
          <span>abort</span>
        </div>

        <button
          onClick={triggerPulse}
          disabled={activeRing >= 3}
          style={{
            height: '38px',
            borderRadius: '10px',
            border: '2px solid #0A0E1A',
            background: activeRing >= 3 ? '#1E2536' : '#2EC4B6',
            color: activeRing >= 3 ? '#6B7489' : '#0A0E1A',
            fontFamily: "'Fredoka', cursive, sans-serif",
            fontWeight: 700,
            fontSize: '14px',
            padding: '0 16px',
            cursor: activeRing >= 3 ? 'not-allowed' : 'pointer',
            boxShadow: activeRing >= 3 ? 'none' : '2px 2px 0 #0A0E1A',
            display: 'inline-flex',
            alignItems: 'center',
            gap: '6px',
          }}>
          <span>Pulse Probe</span>
          <KeyChip label="P" size="sm" />
        </button>
      </div>
    </div>
  );
});

// Subscribed cycle progress bar for action buttons with 60fps direct rAF DOM updates
const CycleProgressBar = React.memo(({
  active,
  getProgress,
}: {
  active: boolean;
  getProgress: () => number;
}) => {
  const barRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!active) return;
    let raf = 0;
    const update = () => {
      if (barRef.current) {
        const pct = Math.min(100, Math.max(0, getProgress() * 100));
        barRef.current.style.width = `${pct}%`;
      }
      raf = requestAnimationFrame(update);
    };
    raf = requestAnimationFrame(update);
    return () => cancelAnimationFrame(raf);
  }, [active, getProgress]);

  if (!active) return null;

  return (
    <div
      style={{
        position: 'absolute',
        bottom: '4px',
        left: '6px',
        right: '6px',
        height: '5px',
        background: '#0F1424',
        borderRadius: '3px',
        overflow: 'hidden',
        pointerEvents: 'none',
      }}>
      <div
        ref={barRef}
        style={{
          height: '100%',
          background: '#FFB547',
          width: '0%',
        }}
      />
    </div>
  );
});

// Slim flat Cel Ink Notice heat meter with tooltip
const NoticeBar = React.memo(({
  notice,
  showTooltip,
  isTooltipVisible,
}: {
  notice: number;
  showTooltip: () => void;
  isTooltipVisible: boolean;
}) => {
  const color = notice >= 100 ? '#FF4D4D' : notice >= 50 ? '#FFB547' : '#2EC4B6';
  return (
    <div
      onMouseEnter={showTooltip}
      onClick={(e) => {
        e.stopPropagation();
        showTooltip();
      }}
      onPointerDown={(e) => e.stopPropagation()}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '3px',
        marginTop: '6px',
        cursor: 'help',
        position: 'relative',
      }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
          <span style={{ fontFamily: "'Inter', sans-serif", fontWeight: 700, fontSize: '11px', color }}>
            NOTICE
          </span>
          <span style={{
            background: '#F6EED8',
            color: '#0A0E1A',
            border: '1.5px solid #0A0E1A',
            borderRadius: '4px',
            padding: '0 4px',
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: '9.5px',
            fontWeight: 700,
            lineHeight: '13px',
          }}>
            [N]
          </span>
        </div>
        <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: '11.5px', fontWeight: 700, color }}>
          {Math.round(notice)}/100
        </span>
      </div>
      <div style={{ height: '8px', background: '#0F1424', border: '2px solid #0A0E1A', borderRadius: '8px', overflow: 'hidden', position: 'relative' }}>
        <div
          style={{
            height: '100%',
            borderRadius: '6px',
            background: color,
            width: `${Math.min(100, Math.max(0, notice))}%`,
            transition: 'width 0.15s ease-out, background-color 0.2s ease',
          }}
        />
      </div>
      {isTooltipVisible && (
        <div
          style={{
            position: 'absolute',
            left: '0px',
            bottom: 'calc(100% + 8px)',
            maxWidth: '280px',
            width: 'max-content',
            whiteSpace: 'normal',
            wordBreak: 'break-word',
            lineHeight: 1.35,
            zIndex: 100,
            background: '#0A0E1A',
            color: '#F6EED8',
            border: '2px solid #FFB547',
            borderRadius: '8px',
            padding: '6px 10px',
            fontSize: '11px',
            fontFamily: "'Inter', sans-serif",
            fontWeight: 500,
            boxShadow: '2px 2px 0 #0A0E1A',
            pointerEvents: 'none',
          }}>
          Mining draws attention. High Notice brings raiders.
        </div>
      )}
    </div>
  );
});

// Asteroid Harmonics & Strain Meter with 10 Hz direct DOM updates
const TargetAsteroidHarmonics = React.memo(({
  rockId,
  laserFreq,
  onSetFreq,
  asteroidsRef,
  laserFreqRef,
}: {
  rockId: string;
  laserFreq: 1 | 2 | 3;
  onSetFreq: (f: 1 | 2 | 3) => void;
  asteroidsRef: React.MutableRefObject<AsteroidEntity[]>;
  laserFreqRef: React.MutableRefObject<1 | 2 | 3>;
}) => {
  const strainValRef = useRef<HTMLSpanElement>(null);
  const freqValRef = useRef<HTMLSpanElement>(null);
  const strainBarRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let raf = 0;
    let lastTime = 0;
    const update = (time: number) => {
      if (time - lastTime >= 100) {
        lastTime = time;
        const rock = asteroidsRef.current.find((a) => a.id === rockId);
        if (rock) {
          const s = Math.round(Math.max(0, Math.min(100, rock.strain || 0)));
          if (strainValRef.current) {
            strainValRef.current.textContent = `STRAIN ${s}%`;
            strainValRef.current.style.color = s > 75 ? '#FF5A5F' : s > 40 ? '#FFB547' : '#2EC4B6';
          }
          if (strainBarRef.current) {
            strainBarRef.current.style.width = `${s}%`;
            strainBarRef.current.style.backgroundColor = s > 75 ? '#FF5A5F' : s > 40 ? '#FFB547' : '#2EC4B6';
          }
          if (freqValRef.current) {
            freqValRef.current.textContent = `FREQ ${laserFreqRef.current} / ${rock.stabilityFreq}`;
          }
        }
      }
      raf = requestAnimationFrame(update);
    };
    raf = requestAnimationFrame(update);
    return () => cancelAnimationFrame(raf);
  }, [rockId, asteroidsRef, laserFreqRef]);

  const rock = asteroidsRef.current.find((a) => a.id === rockId);
  const stabFreq = rock ? rock.stabilityFreq : 2;
  const initialStrain = Math.round(rock ? (rock.strain || 0) : 0);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '3px', marginTop: '4px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span
          ref={freqValRef}
          style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: '11px', fontWeight: 700, color: '#2EC4B6' }}>
          FREQ {laserFreq} / {stabFreq}
        </span>
        <span
          ref={strainValRef}
          style={{
            fontFamily: "'JetBrains Mono', monospace",
            fontSize: '11px',
            fontWeight: 700,
            color: initialStrain > 75 ? '#FF5A5F' : initialStrain > 40 ? '#FFB547' : '#2EC4B6',
          }}>
          STRAIN {initialStrain}%
        </span>
      </div>
      <div style={{ height: '6px', background: '#0F1424', border: '1.5px solid #0A0E1A', borderRadius: '4px', overflow: 'hidden' }}>
        <div
          ref={strainBarRef}
          style={{
            height: '100%',
            background: initialStrain > 75 ? '#FF5A5F' : initialStrain > 40 ? '#FFB547' : '#2EC4B6',
            width: `${initialStrain}%`,
            transition: 'width 0.1s linear',
          }}
        />
      </div>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginTop: '2px' }}>
        <span style={{ fontFamily: "'Inter', sans-serif", fontSize: '11px', color: '#AEB6CA', fontWeight: 600 }}>
          Tune [ <span style={{ color: '#F6EED8' }}>[</span> / <span style={{ color: '#F6EED8' }}>]</span> ]
        </span>
        <div style={{ display: 'flex', gap: '4px' }}>
          {([1, 2, 3] as const).map((f) => {
            const isCur = laserFreq === f;
            const fColor = f === 1 ? '#FFB547' : f === 2 ? '#2EC4B6' : '#B48CFF';
            return (
              <button
                key={f}
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  onSetFreq(f);
                }}
                title={`Tune Laser to Frequency ${f}`}
                style={{
                  width: '22px',
                  height: '19px',
                  borderRadius: '4px',
                  border: isCur ? `2px solid ${fColor}` : '1.5px solid #0A0E1A',
                  background: isCur ? fColor : '#0F1424',
                  color: isCur ? '#0A0E1A' : fColor,
                  fontFamily: "'JetBrains Mono', monospace",
                  fontSize: '11px',
                  fontWeight: 800,
                  cursor: 'pointer',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: 0,
                  boxShadow: isCur ? `0 0 6px ${fColor}` : 'none',
                }}>
                {f}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
});

// Subscribed capacitor gauge with 60fps direct rAF DOM updates
const CapacitorGauge = React.memo(({
  playerRef,
}: {
  playerRef: React.MutableRefObject<any>;
}) => {
  const capRadius = 20;
  const capCircumference = 2 * Math.PI * capRadius;
  const ringRef = useRef<SVGCircleElement>(null);
  const textRef = useRef<SVGTextElement>(null);
  const valRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    let raf = 0;
    const update = () => {
      const p = playerRef.current;
      if (p) {
        const curCap = p.capacitor;
        const maxCap = p.maxCapacitor || 100;
        const capFraction = Math.max(0, Math.min(1, curCap / maxCap));
        const capOffset = capCircumference * (1 - capFraction);
        if (ringRef.current) {
          ringRef.current.style.strokeDashoffset = `${capOffset}`;
        }
        if (textRef.current) {
          textRef.current.textContent = `${Math.round(capFraction * 100)}%`;
        }
        if (valRef.current) {
          valRef.current.textContent = `${Math.round(curCap)}/${maxCap}`;
        }
      }
      raf = requestAnimationFrame(update);
    };
    raf = requestAnimationFrame(update);
    return () => cancelAnimationFrame(raf);
  }, [playerRef, capCircumference]);

  const p = playerRef.current;
  const initialCap = p ? p.capacitor : 100;
  const initialMax = p ? p.maxCapacitor : 100;
  const initialFraction = Math.max(0, Math.min(1, initialCap / initialMax));

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginTop: '1px' }}>
      <div style={{ width: '52px', height: '52px', minWidth: '52px', position: 'relative' }}>
        <svg width="52" height="52" viewBox="0 0 52 52">
          <circle cx="26" cy="26" r="20" fill="none" stroke="#0A0E1A" strokeWidth="12" />
          <circle
            ref={ringRef}
            cx="26"
            cy="26"
            r="20"
            fill="none"
            stroke="#FFD166"
            strokeWidth="7"
            strokeLinecap="round"
            strokeDasharray={capCircumference}
            strokeDashoffset={capCircumference * (1 - initialFraction)}
            transform="rotate(-90 26 26)"
          />
          <text
            ref={textRef}
            x="26"
            y="26"
            style={{
              fontFamily: "'JetBrains Mono', monospace",
              fontSize: '13px',
              fontWeight: 700,
              fill: '#F6EED8',
              textAnchor: 'middle',
              dominantBaseline: 'central',
            }}>
            {Math.round(initialFraction * 100)}%
          </text>
        </svg>
      </div>

      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '2px',
          fontFamily: "'Inter', sans-serif",
          fontSize: '12px',
          color: '#AEB6CA',
        }}>
        <span>
          <span
            ref={valRef}
            style={{ fontFamily: "'JetBrains Mono', monospace", fontWeight: 700, color: '#FFD166' }}>
            {Math.round(initialCap)}/{initialMax}
          </span>{' '}
          capacitor
        </span>
        <span style={{ fontSize: '11px', whiteSpace: 'nowrap' }}>+2.5/s · Mine 12 · Fire 8</span>
      </div>
    </div>
  );
});

// Subscribed overhead badge with 60fps direct rAF DOM updates to decouple walking from full-App React commits
const OfficerOverheadBadge = React.memo(({
  officerXRef,
  isCommsDismissed,
  isAnyPanelOpen,
  terminals,
}: {
  officerXRef: React.MutableRefObject<number>;
  isCommsDismissed: boolean;
  isAnyPanelOpen: boolean;
  terminals: { x: number; tab?: string }[];
}) => {
  const badgeRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let raf = 0;
    const update = () => {
      if (badgeRef.current) {
        if (!isCommsDismissed || isAnyPanelOpen) {
          badgeRef.current.style.display = 'none';
        } else {
          const curX = officerXRef.current;
          let minTermDist = Infinity;
          for (const term of terminals) {
            const stopX = (term.tab ? TERMINAL_INTERACTION_X[term.tab] : undefined) ?? term.x;
            const d = Math.min(Math.abs(curX - term.x), Math.abs(curX - stopX));
            if (d < minTermDist) minTermDist = d;
          }
          const close = minTermDist <= 80;
          if (close) {
            badgeRef.current.style.display = 'block';
            badgeRef.current.style.left = `${curX}px`;
          } else {
            badgeRef.current.style.display = 'none';
          }
        }
      }
      raf = requestAnimationFrame(update);
    };
    raf = requestAnimationFrame(update);
    return () => cancelAnimationFrame(raf);
  }, [officerXRef, isCommsDismissed, isAnyPanelOpen, terminals]);

  return (
    <div
      ref={badgeRef}
      style={{
        position: 'absolute',
        left: `${officerXRef.current}px`,
        top: '452px',
        transform: 'translateX(-50%)',
        zIndex: 35,
        pointerEvents: 'none',
        background: '#2EC4B6',
        color: '#0A0E1A',
        fontFamily: "'Inter', sans-serif",
        fontSize: '12px',
        fontWeight: 800,
        border: '2px solid #0A0E1A',
        borderRadius: '8px',
        padding: '2px 8px',
        boxShadow: '2px 2px 0 #0A0E1A',
        whiteSpace: 'nowrap',
        display: 'none',
      }}>
      YOU · press E
    </div>
  );
});

