const PIXELS_PER_KM = 50;
export { MINING_RANGE_KM };

export function calcSurfaceDistanceKm(px: number, py: number, ast: { x: number; y: number; radius: number; oreReserve?: number; reserve?: number; maxOreReserve?: number; maxReserve?: number }): number {
  const centerDist = Math.hypot(ast.x - px, ast.y - py);
  const reserve = ast.oreReserve ?? ast.reserve ?? 0;
  const maxReserve = ast.maxOreReserve ?? ast.maxReserve ?? 100;
  const r = ast.radius * Math.max(0.6, reserve / (maxReserve || 100));
  return (centerDist - r) / PIXELS_PER_KM;
}

