// Unified Distance Calculation & Formatting (Requirement 7)
export function calcDistanceKm(x1: number, y1: number, x2: number, y2: number): number {
  return Math.hypot(x2 - x1, y2 - y1) / PIXELS_PER_KM;
}

export function formatDistance(distKm: number): string {
  if (!Number.isFinite(distKm)) return '0 m';
  if (distKm < 1.0) {
    return `${Math.round(distKm * 1000)} m`;
  }
  return `${distKm.toFixed(1)} km`;
}

// Robust O(1) angle difference normalization, eliminating infinite while loops (Requirement 6)
export function normalizeAngleDiff(diff: number): number {
  if (!Number.isFinite(diff)) return 0;
  let d = (diff + Math.PI) % (Math.PI * 2);
  if (d < 0) d += Math.PI * 2;
  return d - Math.PI;
}

