export function getStabilityFreq(id: string): 1 | 2 | 3 {
  let sum = 0;
  for (let i = 0; i < id.length; i++) {
    sum += id.charCodeAt(i);
  }
  return ((sum % 3) + 1) as 1 | 2 | 3;
}

