function toSentenceCase(str: string): string {
  if (!str) return '';
  return str.replace(/\b([A-Z])([A-Z]+)\b/g, (match, first, rest) => {
    if (match === 'MARKS' || match === 'HP' || match === 'OK' || match === 'STEP') return match;
    if (['I', 'II', 'III', 'IV', 'V'].includes(match)) return match;
    return first + rest.toLowerCase();
  });
}

function getToastKindColor(toast: ToastNotice): string {
  const t = (toast.type || '').toLowerCase();
  const title = (toast.title || '').toLowerCase();
  const detail = (toast.detail || '').toLowerCase();
  const combined = `${title} ${detail}`;

  if (t === 'warning' || t === 'amber' || combined.includes('subspace erosion') || combined.includes('critical destabilization') || combined.includes('horizon collapse imminent')) {
    return '#FFB547';
  }
  if (t === 'money' || title.includes('marks') || title.includes('credit') || title.includes('bounty') || title.includes('salvage') || title.includes('revenue')) {
    return '#FFB547';
  }
  if (t === 'danger' || combined.includes('hostile') || combined.includes('damage') || combined.includes('warning') || combined.includes('error') || combined.includes('denied') || combined.includes('rejected') || combined.includes('cargo full')) {
    return '#FF5A5F';
  }
  if (t === 'success' || combined.includes('complete') || combined.includes('docked')) {
    return '#8BD17C';
  }
  return '#4CC9F0';
}

