// Station Tab Switcher Header Component for Direct Navigation Between Terminals
const StationTabSwitcher = React.memo(({
  currentTab,
  onSelectTab,
  isOutpost = false,
}: {
  currentTab: string;
  onSelectTab: (tab: 'DOCK' | 'MARKET' | 'FITTING' | 'SKILLS' | 'AGENT' | 'REPAIR' | 'HANGAR' | 'REFINERY' | 'FABRICATOR' | 'BUILD' | 'SCHEMATICS') => void;
  isOutpost?: boolean;
}) => {
  const tabs = isOutpost
    ? [
        { id: 'BUILD' as const, label: 'Build', key: 'B' },
        { id: 'HANGAR' as const, label: 'Hangar', key: '6' },
        { id: 'REFINERY' as const, label: 'Refinery', key: 'R' },
        { id: 'FABRICATOR' as const, label: 'Fabricator', key: 'F' },
        { id: 'SCHEMATICS' as const, label: 'Schematics', key: 'K' },
      ]
    : [
        { id: 'MARKET' as const, label: 'Market', key: '1' },
        { id: 'FITTING' as const, label: 'Fitting', key: '2' },
        { id: 'SKILLS' as const, label: 'Skills', key: '3' },
        { id: 'AGENT' as const, label: 'Agent', key: '4' },
        { id: 'REPAIR' as const, label: 'Repair', key: '5' },
        { id: 'HANGAR' as const, label: 'Hangar', key: '6' },
        { id: 'REFINERY' as const, label: 'Refinery', key: 'R' },
        { id: 'FABRICATOR' as const, label: 'Fabricator', key: 'F' },
        { id: 'SCHEMATICS' as const, label: 'Schematics', key: 'K' },
      ];

  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: '3px', flexWrap: 'nowrap' }}>
      {tabs.map((t) => {
        const isCur = currentTab === t.id;
        const activeColor =
          t.id === 'BUILD' ? '#FFB547' :
          t.id === 'HANGAR' ? '#4CC9F0' :
          t.id === 'MARKET' ? '#FFB547' :
          t.id === 'REFINERY' ? '#FFB547' :
          t.id === 'SCHEMATICS' ? '#2EC4B6' :
          t.id === 'FABRICATOR' ? '#2EC4B6' : '#2EC4B6';
        return (
          <button
            key={t.id}
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onSelectTab(t.id);
            }}
            title={`Switch directly to ${t.label} [${t.key}]`}
            style={{
              background: isCur ? '#0A0E1A' : 'rgba(10, 14, 26, 0.25)',
              color: isCur ? activeColor : '#0A0E1A',
              border: '1.5px solid #0A0E1A',
              borderRadius: '5px',
              padding: '1px 5px',
              fontFamily: "'Fredoka', cursive",
              fontWeight: 700,
              fontSize: '11px',
              cursor: 'pointer',
              lineHeight: '14px',
              boxShadow: isCur ? 'none' : '1px 1px 0 rgba(10, 14, 26, 0.35)',
              transition: 'all 0.1s ease',
              whiteSpace: 'nowrap',
            }}>
            <span>{t.label}</span>{' '}
            <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: '9.5px', opacity: 0.85 }}>[{t.key}]</span>
          </button>
        );
      })}
    </div>
  );
});

