// Canvas procedural glyph fallback for installed hull modules (used when image is loading)
function drawModuleCanvasGlyph(
  ctx: CanvasRenderingContext2D,
  hpId: string,
  cx: number,
  cy: number,
  size: number,
) {
  ctx.save();
  ctx.translate(cx, cy);
  const hs = size / 2;
  ctx.strokeStyle = '#0A0E1A';
  ctx.lineWidth = Math.max(1, size * 0.12);
  ctx.lineJoin = 'round';

  if (hpId === 'armor_plate' || hpId === 'armor') {
    ctx.fillStyle = '#F4A259';
    ctx.beginPath();
    ctx.moveTo(0, -hs);
    ctx.lineTo(hs * 0.8, -hs * 0.5);
    ctx.lineTo(hs * 0.8, hs * 0.2);
    ctx.lineTo(0, hs);
    ctx.lineTo(-hs * 0.8, hs * 0.2);
    ctx.lineTo(-hs * 0.8, -hs * 0.5);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  } else if (hpId === 'cargo_pod' || hpId === 'cargo') {
    ctx.fillStyle = '#FFB547';
    ctx.fillRect(-hs * 0.8, -hs * 0.6, size * 0.8, size * 0.6);
    ctx.strokeRect(-hs * 0.8, -hs * 0.6, size * 0.8, size * 0.6);
    ctx.fillStyle = '#0A0E1A';
    ctx.fillRect(-hs * 0.1, -hs * 0.6, size * 0.1, size * 0.6);
  } else if (hpId === 'thruster') {
    ctx.fillStyle = '#2EC4B6';
    ctx.beginPath();
    ctx.moveTo(-hs * 0.7, -hs * 0.5);
    ctx.lineTo(hs * 0.7, -hs * 0.8);
    ctx.lineTo(hs * 0.7, hs * 0.8);
    ctx.lineTo(-hs * 0.7, hs * 0.5);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  } else {
    // sensor
    ctx.fillStyle = '#2EC4B6';
    ctx.beginPath();
    ctx.arc(0, 0, hs * 0.6, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(0, 0, hs * 0.9, -Math.PI * 0.3, Math.PI * 0.3);
    ctx.stroke();
  }
  ctx.restore();
}

