function getFabricatorAssetSrc(
  id: string,
  assetsRecord: Record<string, HTMLImageElement | null>,
  unkeyedUrls?: Record<string, string>
): string | undefined {
  if (id === 'rift_synchronizer' || id === 'riftSync' || id === 'rift_sync') {
    if (unkeyedUrls && unkeyedUrls['rift_sync']) return unkeyedUrls['rift_sync'];
    const img = assetsRecord['rift_sync'];
    if (img && img.complete && img.naturalWidth > 0) return img.src;
  }
  if (id === 'polymer' || id === 'chemical' || id === 'polymer_composite' || id === 'polymerComposite') {
    const key = id === 'polymerComposite' ? 'polymer_composite' : id;
    if (unkeyedUrls && unkeyedUrls[key]) return unkeyedUrls[key];
    const img = assetsRecord[key];
    if (img && img.complete && img.naturalWidth > 0) return img.src;
  }
  const assetKey = FAB_ITEM_ASSETS.celInk[id];
  if (assetKey) {
    if (unkeyedUrls && unkeyedUrls[assetKey]) {
      return unkeyedUrls[assetKey];
    }
    const img = assetsRecord[assetKey];
    if (img && img.complete && img.naturalWidth > 0) {
      return img.src;
    }
  }
  return undefined;
}

const FabricatorRecipeIcon = React.memo(({ recipeId, src }: { recipeId: string; src?: string }) => {
  const [imgErr, setImgErr] = useState(false);
  useEffect(() => {
    setImgErr(false);
  }, [src]);

  if (src && !imgErr) {
    return (
      <img
        src={src}
        alt=""
        onError={() => setImgErr(true)}
        style={{ width: '36px', height: '36px', objectFit: 'contain', display: 'block' }}
      />
    );
  }
  return <>{renderFabricatorIconFallback(recipeId)}</>;
});

const MarketItemIcon = React.memo(({
  itemKey,
  iconSrc,
  assetsRecord,
  unkeyedUrls,
}: {
  itemKey: string;
  iconSrc?: string;
  assetsRecord: Record<string, HTMLImageElement | null>;
  unkeyedUrls?: Record<string, string>;
}) => {
  const [imgErr, setImgErr] = useState(false);
  useEffect(() => {
    setImgErr(false);
  }, [iconSrc]);

  if (itemKey === 'riftSync' || itemKey === 'rift_synchronizer' || itemKey === 'rift_sync') {
    const rKey = 'rift_sync';
    const rSrc = (unkeyedUrls && unkeyedUrls[rKey]) || (assetsRecord[rKey]?.complete && (assetsRecord[rKey]?.naturalWidth ?? 0) > 0 ? assetsRecord[rKey]?.src : undefined);
    if (rSrc && !imgErr) {
      return <img src={rSrc} alt="" onError={() => setImgErr(true)} style={{ width: '18px', height: '18px', objectFit: 'contain', display: 'block' }} />;
    }
  }
  if (itemKey === 'pristinePrismite' || itemKey === 'pristine_prismite') {
    const rKey = 'pristine_prismite';
    const rSrc = (unkeyedUrls && unkeyedUrls[rKey]) || (assetsRecord[rKey]?.complete && (assetsRecord[rKey]?.naturalWidth ?? 0) > 0 ? assetsRecord[rKey]?.src : undefined);
    if (rSrc && !imgErr) {
      return <img src={rSrc} alt="" onError={() => setImgErr(true)} style={{ width: '18px', height: '18px', objectFit: 'contain', display: 'block' }} />;
    }
  }
  if (itemKey === 'pristineNimbus' || itemKey === 'pristine_nimbus') {
    const rKey = 'pristine_nimbus';
    const rSrc = (unkeyedUrls && unkeyedUrls[rKey]) || (assetsRecord[rKey]?.complete && (assetsRecord[rKey]?.naturalWidth ?? 0) > 0 ? assetsRecord[rKey]?.src : undefined);
    if (rSrc && !imgErr) {
      return <img src={rSrc} alt="" onError={() => setImgErr(true)} style={{ width: '18px', height: '18px', objectFit: 'contain', display: 'block' }} />;
    }
  }
  if (itemKey === 'pristineRadflux' || itemKey === 'pristine_radflux') {
    const rKey = 'pristine_radflux';
    const rSrc = (unkeyedUrls && unkeyedUrls[rKey]) || (assetsRecord[rKey]?.complete && (assetsRecord[rKey]?.naturalWidth ?? 0) > 0 ? assetsRecord[rKey]?.src : undefined);
    if (rSrc && !imgErr) {
      return <img src={rSrc} alt="" onError={() => setImgErr(true)} style={{ width: '18px', height: '18px', objectFit: 'contain', display: 'block' }} />;
    }
  }

  let colonyKey: string | undefined = undefined;
  if (itemKey === 'commandHub' || itemKey === 'hub') colonyKey = COLONY_ASSETS.celInk.hub;
  else if (itemKey === 'drill') colonyKey = COLONY_ASSETS.celInk.drill;
  else if (itemKey === 'processor') colonyKey = COLONY_ASSETS.celInk.processor;
  else if (itemKey === 'pipe') colonyKey = COLONY_ASSETS.celInk.pipe;
  else if (itemKey === 'polymer' || itemKey === 'polymerResin') colonyKey = COLONY_ASSETS.celInk.polymer;
  else if (itemKey === 'chemical' || itemKey === 'reactiveChemicals') colonyKey = COLONY_ASSETS.celInk.chemical;
  else if (itemKey === 'polymerComposite' || itemKey === 'polymer_composite') colonyKey = COLONY_ASSETS.celInk.polymerComposite;
  else if (itemKey === 'icon_drill' || itemKey === 'icon_processor' || itemKey === 'icon_pipe' || itemKey === 'icon_command_hub') colonyKey = itemKey;
  else if ((COLONY_ASSETS.celInk as Record<string, string>)[itemKey]) colonyKey = (COLONY_ASSETS.celInk as Record<string, string>)[itemKey];

  const lensKey = (LENS_ASSETS.celInk as Record<string, string>)[itemKey];
  const droneKey = (DRONE_ASSETS.celInk as Record<string, string>)[itemKey];
  const exoticKey = (EXOTIC_ORE_ASSETS.celInk as Record<string, string>)[itemKey];
  const fabKey = (FAB_ITEM_ASSETS.celInk as Record<string, string>)[itemKey];
  const assetKey = colonyKey || lensKey || droneKey || exoticKey || fabKey || itemKey;
  const unkeyed = assetKey && unkeyedUrls ? unkeyedUrls[assetKey] : undefined;
  const img = assetKey ? assetsRecord[assetKey] : null;
  const src = unkeyed || iconSrc || ((img && img.complete && img.naturalWidth > 0) ? img.src : undefined);

  if (src && !imgErr) {
    return (
      <img
        src={src}
        alt=""
        onError={() => setImgErr(true)}
        style={{ width: '18px', height: '18px', objectFit: 'contain', display: 'block' }}
      />
    );
  }
  return (
    <div style={{ width: '18px', height: '18px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
      {renderFabricatorIconFallback(itemKey)}
    </div>
  );
});

// Unified 2048px High-Res Circular Planet Canvas Pre-Renderer
function buildPlanetCanvas(type: string, img: HTMLImageElement | null): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 2048;
  canvas.height = 2048;
  const ctx = canvas.getContext('2d');
  if (!ctx) return canvas;

  ctx.save();
  // 1. Clip strictly to a circle centered at (1024, 1024) with radius 1020
  ctx.beginPath();
  ctx.arc(1024, 1024, 1020, 0, Math.PI * 2);
  ctx.clip();

  // 2. Base planet color underlayer
  const baseBgColor =
    type === 'volcanic' ? '#181417' :
    type === 'gasGiant' ? '#0F2636' :
    type === 'oceanic' ? '#0F2042' : '#2A303C';
  ctx.fillStyle = baseBgColor;
  ctx.fillRect(0, 0, 2048, 2048);

  // 3. Base Image Blit (centered and aspect-correct, scaled slightly to eliminate baked black rim)
  if (img && img.complete && img.naturalWidth > 0) {
    if (type === 'gasGiant') {
      const sphereRadiusInImg = img.naturalHeight * 0.468;
      const scale = 1020 / sphereRadiusInImg;
      const imgCenterX = img.naturalWidth * 0.49;
      const imgCenterY = img.naturalHeight * 0.498;
      ctx.drawImage(
        img,
        1024 - imgCenterX * scale,
        1024 - imgCenterY * scale,
        img.naturalWidth * scale,
        img.naturalHeight * scale
      );
    } else {
      const minDim = Math.min(img.naturalWidth, img.naturalHeight);
      const scale = 2048 / (minDim * 0.96);
      const cx = img.naturalWidth * 0.5;
      const cy = img.naturalHeight * 0.5;
      ctx.drawImage(
        img,
        1024 - cx * scale,
        1024 - cy * scale,
        img.naturalWidth * scale,
        img.naturalHeight * scale
      );
    }
  }

  // 4. Procedural High-Res Surface Art Details
  if (type === 'barren') {
    // Harrow II: Titanium highlands, craters, fissures, glowing seams
    const highlands = [
      [[700, 350], [950, 420], [1150, 380], [1250, 520], [1100, 680], [850, 650], [680, 520]],
      [[400, 800], [550, 720], [620, 850], [580, 980], [420, 1020], [360, 920]],
      [[750, 950], [920, 880], [1050, 1020], [980, 1200], [820, 1250], [720, 1100]],
      [[1300, 1150], [1480, 1080], [1620, 1220], [1550, 1400], [1380, 1450], [1250, 1320]],
      [[1050, 1450], [1200, 1400], [1320, 1550], [1250, 1720], [1080, 1750], [980, 1620]],
    ];
    highlands.forEach((poly) => {
      ctx.fillStyle = 'rgba(186, 198, 214, 0.45)';
      ctx.beginPath();
      ctx.moveTo(poly[0][0], poly[0][1]);
      for (let i = 1; i < poly.length; i++) ctx.lineTo(poly[i][0], poly[i][1]);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(241, 245, 249, 0.55)';
      ctx.lineWidth = 4;
      ctx.stroke();
    });

    const craters = [
      { x: 720, y: 550, r: 110 },
      { x: 1220, y: 620, r: 160 },
      { x: 1350, y: 1100, r: 190 },
      { x: 780, y: 1220, r: 140 },
      { x: 520, y: 920, r: 95 },
      { x: 1050, y: 880, r: 85 },
      { x: 1480, y: 1420, r: 130 },
      { x: 620, y: 1520, r: 115 },
      { x: 920, y: 1620, r: 100 },
      { x: 1150, y: 1380, r: 75 },
      { x: 420, y: 650, r: 65 },
      { x: 1550, y: 880, r: 80 },
    ];
    craters.forEach((cr) => {
      ctx.fillStyle = 'rgba(20, 24, 34, 0.65)';
      ctx.beginPath();
      ctx.arc(cr.x, cr.y, cr.r, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = '#0A0E1A';
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.arc(cr.x, cr.y, cr.r - 2, 0, Math.PI);
      ctx.stroke();

      ctx.strokeStyle = 'rgba(246, 238, 216, 0.85)';
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.arc(cr.x, cr.y, cr.r, Math.PI, Math.PI * 2);
      ctx.stroke();

      ctx.fillStyle = 'rgba(226, 232, 240, 0.7)';
      ctx.beginPath();
      ctx.arc(cr.x - cr.r * 0.1, cr.y - cr.r * 0.1, cr.r * 0.18, 0, Math.PI * 2);
      ctx.fill();
    });

    const fissures = [
      [[350, 1150], [580, 1080], [740, 1120], [920, 1050], [1150, 1100], [1320, 1020], [1520, 1080]],
      [[740, 1120], [820, 1250], [980, 1380], [1120, 1550], [1280, 1680]],
      [[920, 1050], [980, 880], [1120, 780], [1250, 720]],
      [[580, 1080], [620, 1260], [550, 1420], [680, 1580]],
      [[1320, 1020], [1420, 890], [1580, 820]],
    ];
    fissures.forEach((pts) => {
      ctx.strokeStyle = '#0A0E1A';
      ctx.lineWidth = 14;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.stroke();
    });
    fissures.forEach((pts) => {
      ctx.strokeStyle = '#FF7700';
      ctx.lineWidth = 6;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.stroke();

      ctx.strokeStyle = '#FFD166';
      ctx.lineWidth = 2.5;
      ctx.stroke();
    });
  } else if (type === 'gasGiant') {
    // Harrow V: Swirling atmospheric storm bands, storm eye, ring transit
    const bands = [
      { y: 350, h: 90, color: 'rgba(30, 90, 130, 0.45)', wav: 28 },
      { y: 480, h: 120, color: 'rgba(46, 196, 182, 0.4)', wav: 35 },
      { y: 650, h: 140, color: 'rgba(20, 60, 95, 0.5)', wav: 32 },
      { y: 820, h: 160, color: 'rgba(76, 201, 240, 0.45)', wav: 40 },
      { y: 1020, h: 180, color: 'rgba(25, 75, 115, 0.55)', wav: 36 },
      { y: 1240, h: 150, color: 'rgba(46, 196, 182, 0.42)', wav: 42 },
      { y: 1420, h: 130, color: 'rgba(15, 45, 75, 0.6)', wav: 30 },
      { y: 1600, h: 110, color: 'rgba(76, 201, 240, 0.38)', wav: 25 },
    ];
    bands.forEach((b) => {
      ctx.fillStyle = b.color;
      ctx.beginPath();
      ctx.moveTo(0, b.y);
      for (let x = 0; x <= 2048; x += 64) {
        const ny = b.y + Math.sin(x * 0.008) * b.wav + Math.cos(x * 0.02) * (b.wav * 0.4);
        ctx.lineTo(x, ny);
      }
      ctx.lineTo(2048, b.y + b.h);
      for (let x = 2048; x >= 0; x -= 64) {
        const ny = b.y + b.h + Math.sin(x * 0.008 + 1.2) * b.wav;
        ctx.lineTo(x, ny);
      }
      ctx.closePath();
      ctx.fill();
    });

    ctx.save();
    ctx.translate(1360, 1180);
    for (let ring = 5; ring >= 1; ring--) {
      ctx.fillStyle = ring % 2 === 0 ? 'rgba(46, 196, 182, 0.45)' : 'rgba(15, 60, 95, 0.6)';
      ctx.beginPath();
      ctx.ellipse(0, 0, ring * 42, ring * 28, -Math.PI / 10, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#0A0E1A';
      ctx.lineWidth = 3;
      ctx.stroke();
    }
    ctx.fillStyle = '#64DFDF';
    ctx.beginPath();
    ctx.ellipse(0, 0, 22, 14, -Math.PI / 10, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    ctx.save();
    ctx.translate(1024, 1024);
    ctx.rotate(-0.35);
    ctx.fillStyle = 'rgba(10, 14, 26, 0.35)';
    ctx.fillRect(-1024, 25, 2048, 55);
    ctx.fillStyle = 'rgba(235, 245, 255, 0.45)';
    ctx.fillRect(-1024, -20, 2048, 48);
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.7)';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(-1024, -20);
    ctx.lineTo(1024, -20);
    ctx.moveTo(-1024, 28);
    ctx.lineTo(1024, 28);
    ctx.stroke();
    ctx.restore();
  } else if (type === 'volcanic') {
    // Ember IV: Obsidian crust tectonic plates & glowing lava seams
    const calderas = [
      { x: 650, y: 650, r: 140 },
      { x: 1250, y: 780, r: 170 },
      { x: 1420, y: 1280, r: 150 },
      { x: 750, y: 1350, r: 190 },
      { x: 1050, y: 1100, r: 110 },
      { x: 500, y: 1050, r: 90 },
      { x: 1180, y: 1550, r: 120 },
    ];
    calderas.forEach((cal) => {
      ctx.fillStyle = '#FF3300';
      ctx.beginPath();
      ctx.arc(cal.x, cal.y, cal.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#FF9900';
      ctx.beginPath();
      ctx.arc(cal.x, cal.y, cal.r * 0.7, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#FFDD55';
      ctx.beginPath();
      ctx.arc(cal.x, cal.y, cal.r * 0.4, 0, Math.PI * 2);
      ctx.fill();
    });

    const lavaRivers = [
      [[400, 450], [550, 520], [650, 650], [800, 720], [1050, 750], [1250, 780], [1450, 850], [1650, 800]],
      [[650, 650], [620, 880], [500, 1050], [580, 1220], [750, 1350], [880, 1480], [1180, 1550]],
      [[1050, 750], [1050, 1100], [1150, 1220], [1420, 1280], [1550, 1420]],
      [[1250, 780], [1320, 980], [1420, 1280]],
      [[750, 1350], [850, 1180], [1050, 1100]],
      [[800, 720], [920, 850], [850, 1180]],
    ];
    lavaRivers.forEach((river) => {
      ctx.strokeStyle = '#0A0E1A';
      ctx.lineWidth = 18;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(river[0][0], river[0][1]);
      for (let i = 1; i < river.length; i++) ctx.lineTo(river[i][0], river[i][1]);
      ctx.stroke();

      ctx.strokeStyle = '#FF3B00';
      ctx.lineWidth = 8;
      ctx.stroke();

      ctx.strokeStyle = '#FFD166';
      ctx.lineWidth = 3.5;
      ctx.stroke();
    });
  } else if (type === 'oceanic') {
    // Vael II: Deep oceans, coastal turquoise shelves, archipelago landmasses, cloud spirals
    const continents = [
      [[600, 500], [850, 420], [1050, 480], [1120, 650], [980, 820], [820, 780], [680, 850], [520, 720]],
      [[1200, 700], [1450, 620], [1620, 750], [1580, 950], [1420, 1020], [1280, 920], [1150, 820]],
      [[550, 1050], [750, 980], [880, 1120], [820, 1350], [680, 1450], [520, 1380], [450, 1220]],
      [[1050, 1180], [1280, 1100], [1450, 1250], [1380, 1480], [1220, 1550], [1080, 1420], [980, 1280]],
      [[820, 1450], [980, 1400], [1050, 1580], [920, 1720], [780, 1680], [720, 1550]],
    ];
    continents.forEach((cont) => {
      ctx.fillStyle = 'rgba(46, 196, 182, 0.65)';
      ctx.beginPath();
      ctx.moveTo(cont[0][0], cont[0][1]);
      for (let i = 1; i < cont.length; i++) ctx.lineTo(cont[i][0], cont[i][1]);
      ctx.closePath();
      ctx.lineWidth = 26;
      ctx.strokeStyle = 'rgba(46, 196, 182, 0.65)';
      ctx.lineJoin = 'round';
      ctx.stroke();
      ctx.fill();

      ctx.fillStyle = '#2D6A4F';
      ctx.strokeStyle = '#0A0E1A';
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(cont[0][0], cont[0][1]);
      for (let i = 1; i < cont.length; i++) ctx.lineTo(cont[i][0], cont[i][1]);
      ctx.closePath();
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = '#52B788';
      ctx.beginPath();
      ctx.arc(cont[0][0] * 0.5 + cont[2][0] * 0.5, cont[0][1] * 0.5 + cont[2][1] * 0.5, 45, 0, Math.PI * 2);
      ctx.fill();
    });

    const clouds = [
      [[350, 600], [600, 520], [900, 620], [1250, 580], [1550, 680]],
      [[500, 950], [800, 880], [1150, 920], [1450, 860], [1700, 980]],
      [[400, 1300], [700, 1220], [1050, 1280], [1380, 1200], [1650, 1350]],
      [[750, 1550], [1050, 1480], [1350, 1580]],
    ];
    clouds.forEach((pts) => {
      ctx.strokeStyle = 'rgba(10, 14, 26, 0.28)';
      ctx.lineWidth = 36;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(pts[0][0] + 16, pts[0][1] + 16);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0] + 16, pts[i][1] + 16);
      ctx.stroke();
    });
    clouds.forEach((pts) => {
      ctx.strokeStyle = 'rgba(255, 255, 255, 0.78)';
      ctx.lineWidth = 32;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(pts[0][0], pts[0][1]);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
      ctx.stroke();
    });
  }

  // 5. 3/4 Cel Ink Lighting from Upper-Left (Lit limb & readable terminator)
  const limbGrad = ctx.createRadialGradient(680, 680, 450, 1024, 1024, 1020);
  limbGrad.addColorStop(0, 'rgba(255, 255, 255, 0.18)');
  limbGrad.addColorStop(0.7, 'rgba(255, 255, 255, 0.05)');
  limbGrad.addColorStop(0.94, 'rgba(255, 255, 255, 0.32)');
  limbGrad.addColorStop(1, 'rgba(255, 255, 255, 0)');
  ctx.fillStyle = limbGrad;
  ctx.fillRect(0, 0, 2048, 2048);

  const termGrad = ctx.createLinearGradient(550, 550, 1650, 1650);
  termGrad.addColorStop(0, 'rgba(10, 14, 26, 0)');
  termGrad.addColorStop(0.42, 'rgba(10, 14, 26, 0)');
  termGrad.addColorStop(0.48, 'rgba(10, 14, 26, 0.22)');
  termGrad.addColorStop(0.58, 'rgba(10, 14, 26, 0.40)');
  termGrad.addColorStop(1.0, 'rgba(10, 14, 26, 0.52)');
  ctx.fillStyle = termGrad;
  ctx.fillRect(0, 0, 2048, 2048);

  // 6. Thin 2-3px outline around planet (5px at 2048px resolution)
  ctx.strokeStyle = '#0A0E1A';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(1024, 1024, 1018, 0, Math.PI * 2);
  ctx.stroke();

  ctx.restore();
  return canvas;
}

// APP_FUNC_1
