    const handleKeyUp = (e: KeyboardEvent) => {
      keysDownRef.current[e.key.toLowerCase()] = false;
      keysDownRef.current[e.code.toLowerCase()] = false;
    };
    window.addEventListener('keydown', handleKeyDown);
