  // Live Tutorial Target Rect Tracking
  const [tutTargetRect, setTutTargetRect] = useState<{
    left: number;
    top: number;
    width: number;
    height: number;
  } | null>(null);

  useEffect(() => {
    if (tutorialDone || gameState.status !== 'PLAYING') {
      setTutTargetRect(null);
      return;
    }

    const updateTargetRect = () => {
      let targetKey = '';
      if (tutorialStep === 0) {
        targetKey = 'undock';
      } else if (tutorialStep === 1) {
        targetKey = selectedTargetId === 'belt_alpha' ? 'warp-btn' : 'overview-belt-alpha';
      } else if (tutorialStep === 2) {
        targetKey = 'lock-btn';
      } else if (tutorialStep === 3) {
        targetKey = 'mine-btn';
      } else if (tutorialStep === 4) {
        targetKey = selectedTargetId === 'station' ? 'warp-btn' : 'overview-station';
      } else if (tutorialStep === 5) {
        targetKey = 'dock-btn';
      } else if (tutorialStep === 6) {
        targetKey = stationTab === 'MARKET' ? 'sell-btn' : 'market-tab';
      }

      const rootEl = document.getElementById('game-root');
      const el = rootEl?.querySelector(`[data-tut-target="${targetKey}"]`);
      if (rootEl && el) {
        const rootRect = rootEl.getBoundingClientRect();
        const elRect = el.getBoundingClientRect();
        const s = scale > 0 ? scale : 1;
        const nextRect = {
          left: Math.round((elRect.left - rootRect.left) / s),
          top: Math.round((elRect.top - rootRect.top) / s),
          width: Math.round(elRect.width / s),
          height: Math.round(elRect.height / s),
        };
        setTutTargetRect((prev) => {
          if (
            prev &&
            prev.left === nextRect.left &&
            prev.top === nextRect.top &&
            prev.width === nextRect.width &&
            prev.height === nextRect.height
          ) {
            return prev;
          }
          return nextRect;
        });
      } else {
        const fallbacks: Record<string, {left: number; top: number; width: number; height: number}> = {
          'undock': { left: 1102, top: 723, width: 150, height: 50 },
          'overview-belt-alpha': { left: 988, top: 128, width: 260, height: 30 },
          'warp-btn': { left: 358, top: 704, width: 94, height: 64 },
          'lock-btn': { left: 569, top: 704, width: 94, height: 64 },
          'mine-btn': { left: 777, top: 704, width: 104, height: 64 },
          'overview-station': { left: 988, top: 98, width: 260, height: 30 },
          'dock-btn': { left: 458, top: 704, width: 94, height: 64 },
          'market-tab': { left: 370, top: 723, width: 128, height: 50 },
          'sell-btn': { left: 942, top: 588, width: 170, height: 52 },
        };
        if (fallbacks[targetKey]) {
          const nextRect = fallbacks[targetKey];
          setTutTargetRect((prev) => {
            if (
              prev &&
              prev.left === nextRect.left &&
              prev.top === nextRect.top &&
              prev.width === nextRect.width &&
              prev.height === nextRect.height
            ) {
              return prev;
            }
            return nextRect;
          });
        }
      }
    };

    updateTargetRect();
    const interval = setInterval(updateTargetRect, 150);
    return () => clearInterval(interval);
  }, [tutorialDone, tutorialStep, selectedTargetId, isDocked, stationTab, gameState.status, scale]);

