  const [toasts, setToasts] = useState<ToastNotice[]>([]);
  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const setToastNotice = useCallback(
    (
      val:
        | ToastNotice
        | null
        | ((prev: ToastNotice | null) => ToastNotice | null),
    ) => {
      if (typeof val === 'function') {
        setToasts((prev) => {
          const top = prev[0] || null;
          const res = val(top);
          if (!res) {
            return prev.filter(
              (t) =>
                !(
                  t.title.toLowerCase().includes('cargo full') ||
                  t.id.startsWith('toast_cargofull')
                ),
            );
          }
          const item = { ...res, createdAt: res.createdAt ?? Date.now() };
          return [item, ...prev.filter((t) => t.id !== item.id)].slice(0, 3);
        });
      } else if (!val) {
        setToasts([]);
      } else {
        const item = { ...val, createdAt: val.createdAt ?? Date.now() };
        setToasts((prev) => [item, ...prev.filter((t) => t.id !== item.id)].slice(0, 3));
      }
    },
    [],
  );

  // Auto-dismiss each toast based on its duration (default 4500ms, or explicit duration such as 3000ms for Signal lost)
  useEffect(() => {
    if (toasts.length === 0) return;
    const now = Date.now();
    const timers = toasts.map((toast) => {
      const totalDur = toast.duration ?? 4500;
      const elapsed = now - (toast.createdAt ?? now);
      const remaining = Math.max(100, totalDur - elapsed);
      return setTimeout(() => {
        setToasts((prev) => prev.filter((t) => t.id !== toast.id));
      }, remaining);
    });
    return () => {
      timers.forEach((t) => clearTimeout(t));
    };
  }, [toasts]);

