      const initialMaxShield = Math.round(activeDef.baseShield * (1 + 0.1 * shieldLevel));
      const initialMaxCap = activeDef.baseCap + (capBatteryCountRef.current * 20);
      const effectiveBaseHull = (activeHullRef.current === 'gantry' && gantryRefitRef.current) ? 150 : activeDef.baseHull;

