    cargoThermalGridRef.current = 0;
    cargoPrismiteRef.current = 0;
    cargoNimbusRef.current = 0;
    cargoRadfluxRef.current = 0;
    cargoPackedPrismiteRef.current = 0;
    cargoPackedNimbusRef.current = 0;
    cargoPackedRadfluxRef.current = 0;
    cargoSilicateLensRef.current = 0;
    cargoMetallicLensRef.current = 0;
    cargoExoticLensRef.current = 0;
    cargoExtractDroneRef.current = 0;
    cargoDefenseDroneRef.current = 0;
