    cargoCommandHubRef.current = 0;
    cargoPolymerRef.current = 0;
    cargoChemicalRef.current = 0;
    cargoStationCoreRef.current = 0;
    cargoRiftSyncRef.current = 0;
    cargoPristinePrismiteRef.current = 0;
    cargoPristineNimbusRef.current = 0;
    cargoPristineRadfluxRef.current = 0;
    setRiftStats({ runs: 0, clears: 0, extracts: 0, bestSec: 0 });
    riftStatsRef.current = { runs: 0, clears: 0, extracts: 0, bestSec: 0 };
    setRiftRun(null);
    riftRunRef.current = null;
    coloniesRef.current = {};
    setColonies({});
    setActiveColonyPlanetId(null);
    activeColonyPlanetIdRef.current = null;
    setCargoFerrite(0);
    setCargoRare(0);
    setCargoAurite(0);
    setCargoChromite(0);
    setCargoPyrox(0);
    setCargoScrap(0);
