                              fontFamily: "'Fredoka', cursive, sans-serif",
                              fontWeight: 700,
                              fontSize: '16px',
                              color: '#0A0E1A',
                              letterSpacing: '0.5px',
                              whiteSpace: 'nowrap',
                              overflow: 'hidden',
                              textOverflow: 'ellipsis',
                              flexShrink: 0,
