                  const currentMod = STATION_MODULES_LIST[outpostBuildFocusIndex] || STATION_MODULES_LIST[0];
                  const isInstalled = Boolean(outpostModules[currentMod.id]);
                  const heldPart =
                    currentMod.part === 'hullPlate' ? cargoHullPlate :
                    currentMod.part === 'sensorCore' ? cargoSensorCore :
                    cargoThrusterCoil;
                  const hasPart = heldPart >= 1;
                  const hasMarks = marks >= currentMod.marksCost;
                  const canInstall = hasPart && hasMarks && !isInstalled;

                  const totalVaultStored = Object.values(outpostStorage).reduce((a, b) => a + (b || 0), 0);
                  const isRemovalBlocked = isInstalled && currentMod.id === 'storage_bay' && totalVaultStored > 0;
                  const currentShipVol = getCurrentCargoVolume();
                  const isHoldFullForRefund = isInstalled && (currentShipVol + 5 > cargoMax);

                  const stageW = 520;
                  const stageH = 500;
                  const stageCX = stageW / 2;
                  const stageCY = 230;

