                                    width: `${coreW}px`,
                                    height: `${coreH}px`,
                                    objectFit: 'contain',
                                    pointerEvents: 'none',
                                    zIndex: 2,
                                    filter: 'drop-shadow(0 0 16px rgba(10, 14, 26, 0.95))',
