                                  borderRadius: '24px',
                                  background: '#1D2A44',
                                  border: '4px solid #0A0E1A',
                                  display: 'flex',
                                  flexDirection: 'column',
                                  alignItems: 'center',
                                  justifyContent: 'center',
                                  zIndex: 2,
                                  boxShadow: '0 0 20px rgba(46, 196, 182, 0.3)',
