        const planet = PLANET_DEFS.find((p) => p.id === activeColonyPlanetId);
        if (!planet) return null;
        const colony = coloniesRef.current[planet.id] || { cells: [] };
        const network = getColonyNetwork(colony);

        const curHeat = getPlanetHeat(planet.id, cursorCol, cursorRow);
        const isHubCell = cursorCol === 3 && cursorRow === 2;
        const curCell = isHubCell
          ? null
          : colony.cells.find((c: any) => c.col === cursorCol && c.row === cursorRow);

        const curStructName = isHubCell
          ? 'Command Hub (Central)'
          : curCell
            ? (curCell.type.charAt(0).toUpperCase() + curCell.type.slice(1))
            : 'Empty Terrain';

        const curIsOnline = isHubCell
          ? true
          : curCell
            ? (network.onlineMap.get(`${cursorCol},${cursorRow}`) ?? false)
            : null;

        const rawName = getColonyRawName(planet.id);
        const prodInfo = getColonyProductInfo(planet.type);

        const zone = getPoiZone({ id: planet.id });
        const zoneMult = zone === 'rift' ? 1.5 : zone === 'fringe' ? 1.25 : 1.0;

        let projectedRawPerMin = 0;
        for (const cell of colony.cells) {
          if (cell.type === 'drill' && network.onlineMap.get(`${cell.col},${cell.row}`)) {
            const h = getPlanetHeat(planet.id, cell.col, cell.row);
            const drillYield = Math.floor((2 + Math.floor(h / 20)) * zoneMult);
            projectedRawPerMin += drillYield;
          }
        }
        const projectedProdPerMin = network.onlineProcessors * 3;

        const rawVal = colony.raw || 0;
        const prodVal = colony.product || 0;
        const depotVal = colony.depot || 0;
        const rawFull = rawVal >= 200;
        const storageFull = prodVal >= 98;
        const noProcessor = network.onlineProcessors === 0 && network.onlineDrills > 0;
        const nextCycleSec = Math.max(0, 60 - Math.floor(colony.acc || 0));

        const launchInSec = Math.max(0, Math.ceil(colony.launchIn ?? 300));
        const launchTimerStr = `T-${Math.floor(launchInSec / 60)}:${String(launchInSec % 60).padStart(2, '0')}`;
